'use strict';

// MODULES //

var tape = require( 'tape' );
var isFunction = require( '@stdlib/assert/is-function' );
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var Uint32Array = require( '@stdlib/array/uint32' );
var xorshift128plus = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.ok( isFunction( xorshift128plus ), 'main export is a function' );
	t.end();
});

tape( 'when called with no arguments, returns a pseudorandom number generator function', function test( t ) {
	var rng = xorshift128plus();
	t.ok( isFunction( rng ), 'returns a function' );
	t.end();
});

tape( 'when called with a seed option, returns a PRNG with deterministic output', function test( t ) {
	var rng1;
	var rng2;
	var v1;
	var v2;
	var i;

	rng1 = xorshift128plus({
		'seed': 1234
	});
	rng2 = xorshift128plus({
		'seed': 1234
	});

	for ( i = 0; i < 100; i++ ) {
		v1 = rng1();
		v2 = rng2();
		t.strictEqual( v1, v2, 'same seed produces same output at iteration ' + i );
	}
	t.end();
});

tape( 'when called with different seeds, produces different outputs', function test( t ) {
	var rng1 = xorshift128plus({
		'seed': 111
	});
	var rng2 = xorshift128plus({
		'seed': 222
	});
	var v1 = rng1();
	var v2 = rng2();

	t.notEqual( v1, v2, 'different seeds produce different outputs' );
	t.end();
});

tape( 'generated output is a 32-bit unsigned integer', function test( t ) {
	var rng = xorshift128plus({
		'seed': 12345
	});
	var v;
	var i;

	for ( i = 0; i < 100; i++ ) {
		v = rng();
		t.ok( v >= 0 && v <= 0xffffffff, 'output in range [0, 2^32)' );
		t.ok( Number.isInteger( v ), 'output is integer' );
	}
	t.end();
});

tape( 'generated output is unsigned 32-bit', function test( t ) {
	var rng = xorshift128plus({
		'seed': 9999
	});
	var v;

	v = rng();
	t.ok( v >= 0, 'output >= 0' );
	t.ok( v < 0x100000000, 'output < 2^32' );
	t.end();
});

tape( 'PRNG has a normalized method', function test( t ) {
	var rng = xorshift128plus({
		'seed': 5555
	});
	t.ok( isFunction( rng.normalized ), 'has normalized method' );
	t.end();
});

tape( 'normalized method returns value in [0,1)', function test( t ) {
	var rng = xorshift128plus({
		'seed': 5555
	});
	var v;
	var i;

	for ( i = 0; i < 1000; i++ ) {
		v = rng.normalized();
		t.ok( v >= 0 && v < 1, 'normalized value in [0,1)' );
	}
	t.end();
});

tape( 'PRNG has a seed property', function test( t ) {
	var rng = xorshift128plus({
		'seed': 3333
	});
	t.ok( typeof rng.seed === 'number', 'seed property is a number' );
	t.end();
});

tape( 'PRNG has a state property (getter)', function test( t ) {
	var state;
	var rng = xorshift128plus({
		'seed': 4444
	});
	state = rng.state;

	t.ok( isUint32Array( state ), 'state is a Uint32Array' );
	t.strictEqual( state.length, 4, 'state has length 4' );
	t.end();
});

tape( 'PRNG state property can be set', function test( t ) {
	var state;
	var rng1 = xorshift128plus({
		'seed': 7777
	});
	var rng2 = xorshift128plus({
		'seed': 1111
	});
	var v1;
	var v2;

	// Save state BEFORE generating value
	state = rng1.state;

	// Generate value
	v1 = rng1();

	// Restore state in rng2
	rng2.state = state;

	// Should match
	v2 = rng2();
	t.strictEqual( v1, v2, 'setting state produces same sequence' );

	t.end();
});

tape( 'PRNG has a copy method', function test( t ) {
	var copy;
	var rng = xorshift128plus({
		'seed': 2222
	});

	t.ok( isFunction( rng.copy ), 'has copy method' );

	copy = rng.copy();
	t.ok( isFunction( copy ), 'copy returns a function' );
	t.end();
});

tape( 'copy method creates an independent PRNG at same state', function test( t ) {
	var copy;
	var rng = xorshift128plus({
		'seed': 6666
	});
	var v1;
	var v2;
	var i;

	// Generate some values
	for ( i = 0; i < 10; i++ ) {
		rng();
	}

	// Create copy at current state
	copy = rng.copy();

	// Both should produce same sequence
	for ( i = 0; i < 50; i++ ) {
		v1 = rng();
		v2 = copy();
		t.strictEqual( v1, v2, 'copy at state ' + i + ' produces same output' );
	}
	t.end();
});

tape( 'PRNG has a toJSON method', function test( t ) {
	var json;
	var rng = xorshift128plus({
		'seed': 8888
	});

	t.ok( isFunction( rng.toJSON ), 'has toJSON method' );

	json = rng.toJSON();
	t.ok( typeof json === 'object', 'toJSON returns object' );
	t.strictEqual( json.type, 'PRNG', 'JSON object has type property' );
	t.strictEqual( json.name, 'xorshift128+', 'JSON object has correct name' );
	t.ok( isUint32Array( json.state ), 'JSON state is Uint32Array' );
	t.end();
});

tape( 'NAME property is set correctly', function test( t ) {
	var rng = xorshift128plus({
		'seed': 1111
	});
	t.strictEqual( rng.NAME, 'xorshift128+', 'NAME property is correct' );
	t.end();
});

tape( 'when called with invalid options, throws error', function test( t ) {
	var values;
	var i;

	// Non-object options
	values = [ 'invalid' ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws on non-object options' );
	}

	// Invalid seeds
	values = [ -1, 3.14 ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badSeed( values[i] ), TypeError, 'throws on invalid seed '+values[i] );
	}

	// Invalid state types
	values = [ [] ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badState( values[i] ), TypeError, 'throws on non-Uint32Array state' );
	}

	// Invalid state length
	values = [ new Uint32Array( 2 ) ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badState( values[i] ), RangeError, 'throws on wrong state length' );
	}

	t.end();

	function badValue( value ) {
		return function badValue() {
			xorshift128plus( value );
		};
	}

	function badSeed( value ) {
		return function badSeed() {
			xorshift128plus({
				'seed': value
			});
		};
	}

	function badState( value ) {
		return function badState() {
			xorshift128plus({
				'state': value
			});
		};
	}
});

tape( 'generated sequence has good variety', function test( t ) {
	var values = [];
	var unique;
	var rng = xorshift128plus({
		'seed': 9876
	});
	var i;

	for ( i = 0; i < 1000; i++ ) {
		values.push( rng() );
	}

	unique = new Set( values );
	t.ok( unique.size > 990, 'output values are mostly unique' );
	t.end();
});

tape( 'entropy mixing distributes bits well', function test( t ) {
	var bitCounts = [];
	var count;
	var ratio;
	var rng = xorshift128plus({
		'seed': 5432
	});
	var v;
	var i;
	var b;

	// Initialize bit counters
	for ( b = 0; b < 32; b++ ) {
		bitCounts[ b ] = 0;
	}

	// Generate values and count bits
	for ( i = 0; i < 10000; i++ ) {
		v = rng();
		for ( b = 0; b < 32; b++ ) {
			if ( v & (1 << b) ) {
				bitCounts[ b ] += 1;
			}
		}
	}

	// Check that bits are distributed ~50/50
	count = 0;
	for ( b = 0; b < 32; b++ ) {
		ratio = bitCounts[ b ] / 10000;
		if ( ratio > 0.40 && ratio < 0.60 ) {
			count += 1;
		}
	}

	t.ok( count >= 25, 'most bits (~' + count + '/32) have good distribution' );
	t.end();
});

tape( 'state property returns independent copy', function test( t ) {
	var state2;
	var state1;
	var rng = xorshift128plus({
		'seed': 1357
	});
	state1 = rng.state;
	state2 = rng.state;

	t.notEqual( state1, state2, 'state getter returns new array each time' );

	// Modifying returned state should not affect PRNG
	state1[ 0 ] = 0xffffffff;
	state2 = rng.state;
	t.notEqual( state2[ 0 ], 0xffffffff, 'modifying returned state does not affect PRNG' );
	t.end();
});

tape( 'setting invalid state throws error', function test( t ) {
	var values;
	var rng = xorshift128plus({
		'seed': 2468
	});
	var i;

	// Non-Uint32Array state
	values = [ [] ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws on non-Uint32Array state' );
	}

	// Wrong state length
	values = [ new Uint32Array( 2 ) ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badRange( values[i] ), RangeError, 'throws on wrong state length' );
	}

	t.end();

	function badValue( value ) {
		return function badValue() {
			rng.state = value;
		};
	}

	function badRange( value ) {
		return function badRange() {
			rng.state = value;
		};
	}
});

tape( 'normalized output matches formula', function test( t ) {
	var expected;
	var vNorm;
	var rng2 = xorshift128plus({
		'seed': 4680
	});
	var rng = xorshift128plus({
		'seed': 4680
	});
	expected = (rng2() / 0x100000000);
	vNorm = rng.normalized();

	t.strictEqual( vNorm, expected, 'normalized output matches formula' );
	t.end();
});

tape( 'PRNG state can be restored and continued', function test( t ) {
	var state;
	var rng1 = xorshift128plus({
		'seed': 5791
	});
	var rng2 = xorshift128plus({
		'seed': 9999
	});
	var v1;
	var v2;
	var i;

	// Generate some values from rng1
	for ( i = 0; i < 50; i++ ) {
		rng1();
	}

	// Save state
	state = rng1.state;

	// Set rng2 to this state
	rng2.state = state;

	// Continue and verify same sequence
	for ( i = 0; i < 100; i++ ) {
		v1 = rng1();
		v2 = rng2();
		t.strictEqual( v1, v2, 'restored state produces same continuation at ' + i );
	}
	t.end();
});
